import {freshState,DEMO_TODAY as TODAY} from './demo-data.js';
import {shift,weekday,remaining,validateAllocation,reconcile,followup} from './rules.js';
const KEY='po-design-prototype-v1';
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.version!==1)state=null;}catch{}state??=freshState();
let selected=TODAY,month='2026-10-01',view='month',type='all',customer='all',search='',detailTab='overview';
const paths={calendar:'M3 5h18v16H3z M7 2v6 M17 2v6 M3 10h18',orders:'M5 3h14v18H5z M8 8h8 M8 12h8 M8 16h5',upload:'M12 16V3 M7 8l5-5 5 5 M4 14v7h16v-7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',history:'M3 12a9 9 0 1 0 3-7 M3 3v6h6 M12 7v6l4 2',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M18 5a3 3 0 0 1 0 6 M22 21v-3a4 4 0 0 0-3-4',guide:'M3 3h7l2 2 2-2h7v17h-7l-2 2-2-2H3z M12 5v17',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',check:'M5 12l4 4 10-10',warning:'M12 3L2 21h20z M12 9v5 M12 17v1',close:'M6 6l12 12 M6 18L18 6',box:'M3 7l9-4 9 4v11l-9 4-9-4z M3 7l9 4 9-4 M12 11v11'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.box}"></path></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number(v).toLocaleString('en-US',{maximumFractionDigits:10});
const money=o=>`${o.currency} ${num(o.qty*Number(o.price))}`;
const short=s=>s?s.slice(5).replace('-','.'): '미정';
const korean=s=>s?`${Number(s.slice(5,7))}월 ${Number(s.slice(8,10))}일 ${['일','월','화','수','목','금','토'][weekday(s)]}요일`:'날짜 미정';
const badge=(text,cls='')=>`<span class="pill ${cls}">${esc(text)}</span>`;
const btn=(text,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const order=id=>state.orders.find(o=>o.id===id);
const done=t=>t.steps.every(s=>s.done);
const status=t=>t.cancelled?'cancelled':done(t)?'done':!t.date?'unknown':t.date<TODAY?'overdue':t.steps.some(s=>s.done)?'partial':'open';
const labels={done:'완료',partial:'부분완료',open:'미완료',overdue:'지연',unknown:'날짜 미정',cancelled:'취소'};
const save=()=>localStorage.setItem(KEY,JSON.stringify(state));
function toast(text){const e=document.querySelector('#toast');e.textContent=text;e.classList.add('visible');setTimeout(()=>e.classList.remove('visible'),3200);}
function visible(t){const o=order(t.order);return(type==='all'||o.type===type)&&(customer==='all'||o.customer===customer);}
function nav(){const section=location.hash.slice(2).split('/')[0]||'calendar';const items=[['calendar','업무 달력'],['orders','PO 목록'],['upload','PO 파일 등록'],['settings','문자 알림 설정'],['history','문자 발송 이력'],['users','계정·권한 관리'],['guide','목업 사용 안내']];return `<aside class="sidebar"><a href="#/calendar" class="brand"><span class="brand-mark">P</span><span>PO Desk<small>ORDER WORKSPACE</small></span></a><p class="nav-label">WORKSPACE</p><nav class="nav-list">${items.map(([key,title],i)=>`${i===3?'<div class="nav-separator"></div>':''}<a href="#/${key}" class="nav ${section===key?'active':''}">${icon(key)}${title}</a>`).join('')}</nav><div class="sidebar-bottom"><p><span class="dot"></span>2026.10.16 최종 설계 기준</p><small>예시 데이터로 동작하는 UI 목업입니다.<br>실제 등록·문자 발송은 하지 않습니다.</small><p>${btn('예시 데이터 초기화','reset','quiet small')}</p></div></aside>`;}
function header(title,sub,action=''){return `<section class="page-head"><div><div class="eyebrow">ORDER MANAGEMENT / WORKSPACE</div><h1>${title}</h1><p>${sub}</p></div>${action}</section>`;}
function shell(content){document.querySelector('#app').innerHTML=`<div class="shell">${nav()}<div class="workspace"><header class="topbar"><span>영업관리 워크스페이스 <span style="margin:0 9px;color:#c2cbd7">/</span> PO 관리</span><div class="account"><span class="prototype">UI 목업 · 예시 데이터</span><span>김담당</span><span class="avatar">김</span></div></header><main>${content}<footer class="page-foot"><span>PO Desk · 2026.10.16 최종 설계 / 예시 기준일 2026.10.19 (월)</span><span>실제 ERP·메일·Excel 작업은 담당자가 직접 처리합니다.</span></footer></main></div></div>`;}
function stats(){const active=state.tasks.filter(t=>!done(t)&&!t.cancelled);return `<section class="stats">${[
 ['오늘 해야 할 업무',active.filter(t=>t.date===TODAY).length,'오늘의 일정에서 완료 여부를 확인하세요','calendar','blue'],
 ['지연된 업무',active.filter(t=>t.date&&t.date<TODAY).length,'남은 작업은 평일 09시에 다시 안내','history','amber'],
 ['진행 중인 PO',state.orders.filter(o=>remaining(o.qty,o.shipments,o.cancelledQty)>0&&!o.cancelled).length,'출고실적 기준으로 잔량을 계산합니다','orders',''],
 ['ETD 미정 회차',state.orders.filter(o=>o.type==='overseas').flatMap(o=>o.shipments).filter(s=>!s.etd&&!s.cancelled).length,'ETD 입력 전 후속업무·문자 보류','box','teal']
 ].map(([label,value,tip,i,color])=>`<article class="card stat"><span class="stat-label">${label}</span><span class="stat-icon">${icon(i)}</span><strong class="stat-number ${color}">${value}<small>건</small></strong><p>${tip}</p></article>`).join('')}</section>`;}
function taskRow(t){const o=order(t.order);const count=t.steps.filter(s=>s.done).length;return `<button class="task-row" data-task="${t.id}"><div class="row between"><strong>${esc(o.customer)}</strong>${badge(labels[status(t)],status(t))}</div><p style="color:#425a78">${esc(t.title)}</p><p>${esc(o.po)}${t.shipment?' · '+(o.shipments.findIndex(s=>s.id===t.shipment)+1)+'차':''} <span style="float:right">${count}/${t.steps.length} 완료</span></p>${t.review?badge('변경 후 재확인 필요','partial'):''}${t.manual?badge('수동 지정','manual'):''}</button>`;}
function filters(){return `<section class="filters"><div class="segments">${[['all','전체'],['domestic','국내'],['overseas','해외']].map(([key,title])=>`<button data-filter="${key}" class="${type===key?'active':''}">${title}</button>`).join('')}</div><label class="sr-only" for="customer-filter">고객 필터</label><select id="customer-filter"><option value="all">모든 고객</option>${[...new Set(state.orders.map(o=>o.customer))].map(name=>`<option value="${esc(name)}" ${customer===name?'selected':''}>${esc(name)}</option>`).join('')}</select><span class="filter-spacer"></span><span class="muted" style="font-size:10px">한국시간 · 주말 자동 보정</span></section>`;}
function calendar(){
 const [year,m]=month.split('-').map(Number);const first=`${year}-${String(m).padStart(2,'0')}-01`;let start=shift(first,-((weekday(first)+6)%7));let length=35;
 if(view==='week'){start=shift(selected,-((weekday(selected)+6)%7));length=7;}else{const last=new Date(Date.UTC(year,m,0)).getUTCDate();if(((weekday(first)+6)%7)+last>35)length=42;}
 const tasks=state.tasks.filter(visible);const todays=tasks.filter(t=>t.date===selected&&!t.cancelled);const undated=tasks.filter(t=>!t.date&&!done(t)&&!t.cancelled);
 const cells=Array.from({length},(_,i)=>{const d=shift(start,i);const dayTasks=tasks.filter(t=>t.date===d&&!t.cancelled);const groups=new Map();for(const t of dayTasks){const key=t.kind;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(t);}const entries=[...groups.values()].map(ts=>{const names=[...new Set(ts.map(t=>order(t.order).customer))];const title=ts[0].kind==='share'?names.join(',')+'(출고 내역 공유)':ts[0].title+(ts.length>1?` · ${ts.length}건`:'');return {title,cls:ts.every(done)?'done':d<TODAY?'overdue':ts.every(t=>order(t.order).type==='overseas')?'overseas':''};});
  for(const o of state.orders.filter(o=>o.type==='domestic'&&!o.cancelled&&(type==='all'||type==='domestic')&&(customer==='all'||o.customer===customer))){if(o.due===d)entries.push({title:o.customer+'(납기)',cls:'due'});}
  return `<div class="calendar-day ${d.slice(0,7)!==month.slice(0,7)?'outside':''} ${d===selected?'selected':''}"><button class="day-number ${d===TODAY?'today':''}" data-date="${d}" aria-label="${d} 업무 선택">${Number(d.slice(8))}</button>${entries.slice(0,view==='week'?20:3).map(e=>`<button class="event ${e.cls}" data-date="${d}" title="${esc(e.title)}">${esc(e.title)}</button>`).join('')}${entries.length>3&&view!=='week'?`<button class="more" data-date="${d}">+${entries.length-3}개 더 보기</button>`:''}</div>`;
 }).join('');
 shell(`${header('업무 달력','오늘의 할 일을 확인하고, PO부터 출고까지 놓치지 않도록.',`<a class="btn primary" href="#/upload">${icon('plus')} PO 파일 등록</a>`)}${stats()}<div class="alert"><span class="row">${icon('warning')}10.16 문자 알림 1건이 최종 실패했습니다. 발송 이력에서 사유를 확인하세요.</span><a href="#/history">이력 확인 →</a></div>${filters()}<div class="calendar-layout"><section class="card"><div class="calendar-toolbar"><div class="row">${btn('‹','previous','small','aria-label="이전 기간"')}<h2>${year}년 ${m}월</h2>${btn('›','next','small','aria-label="다음 기간"')}${btn('오늘','today','small')}</div><div class="segments"><button data-view="month" class="${view==='month'?'active':''}">월간</button><button data-view="week" class="${view==='week'?'active':''}">주간</button></div></div><div class="week-labels">${['월','화','수','목','금','토','일'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid ${view==='week'?'week-mode':''}">${cells}</div><div class="legend"><span><i></i>국내 업무</span><span><i class="green"></i>해외 업무</span><span><i class="gray"></i>완료 / 납기</span><span>납기는 완료 체크 대상에서 제외</span></div></section><aside class="card agenda"><div class="agenda-title"><div class="row between"><h2>${korean(selected)}</h2>${badge(todays.length+'건')}</div><p>업무를 선택하면 세부 작업을 확인합니다.</p></div>${todays.length?todays.map(taskRow).join(''):'<p class="empty">이 날짜에 배치된 업무가 없습니다.</p>'}<div class="agenda-divider"><h3>ETD를 기다리고 있어요 ${badge(undated.length+'건','unknown')}</h3><p>ETD 미정 후속업무는 달력과 문자에 포함되지 않습니다.</p></div>${[...new Set(undated.map(t=>t.order))].map(id=>`<a class="task-row" href="#/orders/${id}"><strong>${esc(order(id).customer)}</strong><p>${esc(order(id).po)} · ETD 입력하기 →</p></a>`).join('')}</aside></div>`);
}
function ordersPage(){const rows=state.orders.filter(o=>(type==='all'||type===o.type)&&(`${o.customer} ${o.po} ${o.code} ${o.name}`).toLowerCase().includes(search.toLowerCase()));shell(`${header('PO 목록','고객별 주문과 출고 진행상황을 한 곳에서 확인합니다.',`<div class="row"><a class="btn" href="#/upload?manual">직접 입력</a><a class="btn primary" href="#/upload">${icon('plus')} PO 파일 등록</a></div>`)}${stats()}<div class="filters"><div class="segments">${[['all','전체'],['domestic','국내'],['overseas','해외']].map(([key,title])=>`<button data-filter="${key}" class="${type===key?'active':''}">${title}</button>`).join('')}</div><label for="order-search" class="sr-only">고객·PO·품목 검색</label><input id="order-search" class="search filter-spacer" placeholder="고객·PO 번호·품목 검색" value="${esc(search)}"></div><section class="card"><div class="card-head"><h2>전체 PO <span class="muted">${rows.length}</span></h2><small>품목별 수량·원본·변경 이력 보관</small></div><div class="table-scroll"><table><thead><tr><th>고객 / PO 번호</th><th>구분</th><th>품목</th><th class="numeric">주문수량</th><th>출고 진행</th><th class="numeric">잔량</th><th>다음 일정</th><th></th></tr></thead><tbody>${rows.map(o=>{const rem=remaining(o.qty,o.shipments,o.cancelledQty);const shipped=o.qty-rem-o.cancelledQty;const next=state.tasks.filter(t=>t.order===o.id&&t.date&&!done(t)&&!t.cancelled).sort((a,b)=>a.date.localeCompare(b.date))[0];return `<tr class="click-row" data-order="${o.id}"><td><strong>${esc(o.customer)}</strong><small>${esc(o.po)}</small></td><td>${badge(o.type==='domestic'?'국내':'해외',o.type)}</td><td>${esc(o.code)}<small>${esc(o.name)}</small></td><td class="numeric">${num(o.qty)} ${o.unit}</td><td>${num(shipped)} / ${num(o.qty)}<div class="progress"><span style="width:${100*shipped/o.qty}%"></span></div></td><td class="numeric"><strong class="${rem?'blue':'teal'}">${num(rem)}</strong></td><td>${next?`${short(next.date)}<small>${esc(next.title)}</small>`:badge('처리 완료','done')}</td><td><a href="#/orders/${o.id}" aria-label="${esc(o.customer)} PO 상세">→</a></td></tr>`;}).join('')}</tbody></table></div></section><div class="demo-note">예시: 범진전자 100 EA 중 1차 70 EA만 출고 완료되어 잔량은 30 EA입니다. 2차 수량을 배정해도 출고 완료 전에는 실적으로 계산하지 않습니다.</div>`);}
function detail(id){const o=order(id);if(!o){location.hash='#/orders';return;}const rem=remaining(o.qty,o.shipments,o.cancelledQty),shipped=o.qty-rem-o.cancelledQty;const tasks=state.tasks.filter(t=>t.order===o.id);const main=`<div class="card"><div class="card-head"><h2>품목 및 주문수량</h2>${badge(o.currency+' 거래',o.type)}</div><div class="table-scroll"><table><thead><tr><th>품목코드 / 품명·모델</th><th class="numeric">주문</th><th class="numeric">출고</th><th class="numeric">취소</th><th class="numeric">잔량</th><th class="numeric">단가 / 공급가액</th></tr></thead><tbody><tr><td><strong>${esc(o.code)}</strong><small>${esc(o.name)}</small></td><td class="numeric">${num(o.qty)} ${o.unit}</td><td class="numeric">${num(shipped)}</td><td class="numeric">${num(o.cancelledQty)}</td><td class="numeric blue"><b>${num(rem)}</b></td><td class="numeric">${o.price} ${o.currency}<small>${money(o)}</small></td></tr></tbody></table></div><div class="card-body"><small>원문 요청납기 ${o.due}${o.type==='overseas'?' · 원문 보존용이며 해외 일정 계산과 달력 표시에서 제외합니다.':''}</small></div></div><section class="card"><div class="card-head"><h2>${o.type==='domestic'?'출고':'선적'}회차</h2>${btn('+ 회차 추가','add-shipment','small',`data-id="${o.id}"`)}</div>${o.shipments.map((s,i)=>`<article class="shipment"><div class="row between"><h3>${i+1}차 ${badge(s.cancelled?'취소':s.done?'출고 완료':'출고 대기',s.cancelled?'cancelled':s.done?'done':'open')}</h3><small>${esc(o.code)}</small></div><div class="shipment-grid"><div><small>회차 수량</small><strong>${num(s.qty)} ${o.unit}</strong></div>${o.type==='domestic'?`<div><small>출고일</small><strong>${s.date}</strong></div>`:`<div><small>ETD</small><strong>${s.etd||'<span class="amber">미정</span>'}</strong></div><div><small>ETA · 고객 안내용</small><strong>${s.eta||'미정'}</strong></div>`}</div>${!s.etd&&o.type==='overseas'&&!s.cancelled?'<p class="note">ETD 미정 · ERP 2개 처리, 출고 메일, 엑셀 기입 업무의 날짜와 문자를 보류합니다.</p>':''}<div class="shipment-actions">${!s.done&&!s.cancelled?btn('날짜·수량 수정','edit-shipment','small',`data-id="${o.id}" data-shipment="${s.id}"`)+btn('출고 완료','confirm-shipment','primary small',`data-id="${o.id}" data-shipment="${s.id}"`)+btn('회차 취소','cancel-shipment','quiet small',`data-id="${o.id}" data-shipment="${s.id}"`):s.done?btn(o.type==='overseas'?'ETA 수정':'실적 정정','edit-shipment','small',`data-id="${o.id}" data-shipment="${s.id}"`):''}</div></article>`).join('')}</section>`;
 shell(`${header(`${esc(o.customer)} <span style="font-size:14px;vertical-align:middle">${badge(o.type==='domestic'?'국내':'해외',o.type)}</span>`,`${esc(o.po)} · 고객 담당자 ${esc(o.contact)}`,`<a class="btn" href="#/orders">← PO 목록</a>`)}<section class="card card-body detail-top"><div><div class="row">${badge(rem>0?'출고 진행 중':'출고 완료',rem>0?'domestic':'done')}<small>PO 수령 ${o.received}</small></div><div class="detail-meta"><div><small>주문수량</small><b>${num(o.qty)} ${o.unit}</b></div><div><small>누적 출고</small><b>${num(shipped)} ${o.unit}</b></div><div><small>남은 출고 대상</small><b class="blue">${num(rem)} ${o.unit}</b></div></div></div><div><small>공급가액</small><p class="amount">${money(o)}</p></div></section><div class="tabs">${[['overview','품목·출고'],['tasks','업무 '+tasks.length],['files','원본·변경 이력']].map(([key,title])=>`<button data-detail-tab="${key}" class="${detailTab===key?'active':''}">${title}</button>`).join('')}</div><div class="split"><div class="stack">${detailTab==='overview'?main:detailTab==='tasks'?`<section class="card">${tasks.map(taskRow).join('')}</section>`:`<section class="card card-body"><h2>원본 파일 · 버전 1</h2><p class="note">예시_PO_${esc(o.po)}.pdf · 등록 시 원본을 보관합니다.</p><a class="btn small" href="#/upload">확인 화면 보기</a><h2 style="margin-top:28px">변경 이력</h2><div class="timeline">${o.history.map(h=>`<p>${esc(h)}</p>`).join('')}</div></section>`}</div><aside class="stack"><section class="card card-body"><h2>처리 전 확인</h2><p class="note">업무 완료와 출고 완료는 별개입니다. 실제 출고한 회차만 출고 완료를 눌러 실적으로 확정하세요.</p><p class="note">${o.type==='domestic'?`이 거래의 ERP 메뉴<br><b>${o.currency==='USD'?'출고의뢰등록(수출) / 거래명세서(수출)':'출고의뢰등록 / 출고처리'}</b>`:'BL·ETA 공유는 PO 수령일 기준 차주 화요일입니다. ETD 후속업무는 선적일 다음 평일로 계산합니다.'}</p></section><section class="card card-body"><h2>최근 변경</h2><div class="timeline">${o.history.slice(0,3).map(h=>`<p>${esc(h)}</p>`).join('')}</div></section></aside></div>`);
}
function upload(){shell(`${header('PO 파일 등록','원본을 확인하고, 인식한 내용을 수정한 뒤 등록합니다.')}<div class="steps"><b>01 파일 선택</b><span>→</span><span>02 인식 결과 확인</span><span>→</span><span>03 등록·업무 생성</span></div><div class="review-layout"><section class="card card-body"><div class="upload-zone">${icon('upload')}<h3>PO 파일을 여기에 놓아주세요</h3><p>PDF · Excel (.xlsx, .xls) / 최대 20 MB</p><label class="btn primary" for="sample-file">파일 선택</label><input id="sample-file" type="file" accept=".pdf,.xlsx,.xls" hidden><p id="file-name" style="margin-top:15px">목업에서는 예시 인식값으로 화면을 체험합니다.</p></div><div class="demo-note">이 목업은 실제 파일을 분석하거나 서버에 전송하지 않습니다. 아래 예시 문서는 화면 검토용입니다.</div><div style="margin-top:19px"><h2>예시 원본 미리보기</h2><div class="paper-wrap"><div class="paper"><h2>Purchase Order</h2><p><b>PO no.</b> &emsp; DEMO-BJ-100<br><b>PO Date</b> &emsp; 2026.10.19</p><p><b>Buyer</b><br>BUMJIN ELECTRONICS CO.,LTD</p><table><thead><tr><th>Material</th><th>Description / Specification</th><th>Quantity</th><th>Price / Delivery</th></tr></thead><tbody><tr><td>SW-DEMO</td><td>TACT SWITCH<br>JTP1280A6</td><td class="highlight">100 EA</td><td>USD 0.0145<br>2026.10.23</td></tr></tbody></table><p style="margin-top:24px;text-align:right">Total Amount &nbsp; USD 1.45</p><div class="paper-footer">예시 원본 · 실제 고객 문서를 복제한 자료가 아닙니다.</div></div></div></div></section><section class="card"><div class="card-head"><h2>인식 결과 확인</h2>${badge('직접 확인 필요','partial')}</div><form id="review-form" class="card-body"><div class="form-grid"><label class="field">고객사명<select name="customer"><option>범진전자</option><option>한빛테크</option><option>비나일렉트로닉스</option></select><span class="field-origin">원본 Buyer ↔ 기존 고객 연결</span></label><label class="field">국내·해외 구분<select name="type"><option value="domestic">국내</option><option value="overseas">해외</option></select></label><label class="field">PO 번호<input name="po" value="DEMO-BJ-100" required></label><label class="field">PO 주문일<input type="date" value="2026-10-19"></label><label class="field">실제 PO 수령일<input name="received" type="date" value="2026-10-19" required><small>업로드일을 제안합니다. 실제 수령일을 확인하세요.</small></label><label class="field">고객 담당자<input name="contact" value="구매팀 김담당"></label></div><div class="review-line"><div class="row between" style="margin-bottom:17px"><h3 style="margin:0">품목 01</h3>${badge('원본과 비교')}</div><div class="form-grid"><label class="field">품목코드<input name="code" value="SW-DEMO" required></label><label class="field">품명·모델명<input name="name" value="TACT SWITCH · JTP1280A6" required></label><label class="field">주문수량<input name="qty" type="number" min="0.0000000001" step="any" value="100" required></label><label class="field">단위<input name="unit" value="EA" required></label><label class="field">단가<input name="price" type="number" min="0" step="any" value="0.0145" required></label><label class="field">통화<select name="currency"><option>USD</option><option>KRW</option></select></label><label class="field wide">원문 요청납기<input name="due" type="date" value="2026-10-23" required><small>국내는 초기 출고일을 제안합니다. 해외는 원문 보존용이며 일정 계산에서 제외합니다.</small></label></div></div><p class="note">누락한 값은 추측하지 않습니다. 등록 전 수량·단가·납기를 원본과 비교하세요. 해외 ETD는 미정으로 등록할 수 있습니다.</p><div class="row between" style="margin-top:23px"><a href="#/orders" class="btn">취소</a><button type="submit" class="btn primary">확인 후 예시 PO 등록 →</button></div></form></section></div>`);}
function settings(){shell(`${header('문자 알림 설정','내가 처리해야 할 업무를 평일 오전 9시에 안내받습니다.')}<div class="settings-grid"><form id="notice-form" class="stack"><section class="card"><div class="card-head"><h2>내 휴대폰 알림</h2>${badge('사용자 본인에게만 발송','domestic')}</div><div class="card-body"><label class="switch"><input type="checkbox" name="enabled" ${state.notice.enabled?'checked':''}> 평일 업무 알림 사용</label><div class="form-grid" style="margin-top:25px"><label class="field">내 휴대폰 번호<input name="recipient" value="${esc(state.notice.recipient)}" required><small>고객이 아닌 사용자 본인의 번호입니다.</small></label><label class="field">등록된 발신번호<input name="sender" value="${esc(state.notice.sender)}" required><small>문자 공급자에 사전 등록한 번호를 사용합니다.</small></label></div></div></section><section class="card card-body"><h2>발송 기준</h2><dl class="definition"><dt>정기 알림</dt><dd>평일 오전 09:00 · 한국시간</dd><dt>포함할 업무</dt><dd>오늘 + 이전 날짜의 미완료·부분완료 업무</dd><dt>당일 추가 알림</dt><dd>정기 발송 후 새로 생긴 당일 업무만 안내</dd><dt>알림 날짜</dt><dd>달력에 최종 배치한 업무일 기준</dd><dt>보류 대상</dt><dd>완료·취소·날짜 미정 / 납기 표시</dd><dt>명확한 실패</dt><dd>5분 간격으로 최대 3회 재시도</dd><dt>결과 불명확</dt><dd>발송 내역 확인 후 처리 · 즉시 재발송 안 함</dd></dl></section><div class="row between"><small>인증정보는 이 목업에 저장하거나 입력하지 않습니다.</small><button class="btn primary">목업 설정 저장</button></div></form><aside class="card"><div class="card-head"><h2>문자 미리보기</h2>${badge('예시')}</div><div class="card-body"><div class="phone"><div class="phone-top">오늘 09:00 · PO 업무 알림</div><div class="bubble">[PO 업무 알림]

오늘 · 10월 19일
범진전자 — 명세서 공유, 엑셀 기입, 전표 인쇄
비나일렉트로닉스 — 인보이스+ERP
알파컴포넌트 — 입고처리(수입) 미완료

지연
한빛테크 — 출고 내역 공유, 출고의뢰 등록·인쇄, 구매팀 전달

상세는 업무 달력에서 확인하세요.</div><p>예시 메시지 · 실제로 발송되지 않습니다.</p></div><p class="note">문자는 업무를 안내합니다. ERP 등록, 메일 발송, Excel 입력은 직접 수행합니다.</p></div></aside></div>`);}
function history(){shell(`${header('문자 발송 이력','정기·추가 알림의 요청부터 최종 결과까지 확인합니다.',`<a class="btn" href="#/settings">알림 설정</a>`)}<div class="alert"><span class="row">${icon('warning')}결과 확인 중인 문자는 공급자 내역을 확인하기 전 다시 보내지 않습니다.</span></div><section class="card"><div class="card-head"><h2>최근 발송</h2><small>예시 데이터 · 실제 문자 발송 없음</small></div><div class="table-scroll"><table><thead><tr><th>요청 시각</th><th>종류</th><th>수신자</th><th>업무 수</th><th>시도 횟수</th><th>최종 상태</th><th></th></tr></thead><tbody>${state.history.map(n=>`<tr><td>${n.at}</td><td>${n.kind}</td><td>010-****-0000<small>사용자 본인</small></td><td>${n.count}건</td><td>${n.attempt}회</td><td>${badge(n.status,n.status==='전달 완료'?'done':n.status==='최종 실패'?'failed':'unknown')}</td><td>${btn('상세 보기','notice-detail','small',`data-id="${n.id}"`)}</td></tr>`).join('')}</tbody></table></div></section><div class="demo-note">접수 완료와 전달 완료는 구분합니다. 명확한 실패만 최초 발송 이후 5분 간격으로 3회까지 재시도하며, 결과가 불명확하면 먼저 공급자 기록을 조회합니다.</div>`);}
function users(){shell(`${header('계정·권한 관리','업무담당자는 PO를 공동 관리하고, 관리자는 계정을 관리합니다.')}<section class="card"><div class="card-head"><h2>사용자</h2>${badge('관리자 전용','domestic')}</div><div class="table-scroll"><table><thead><tr><th>사용자</th><th>권한</th><th>상태</th><th>접근 범위</th></tr></thead><tbody><tr><td>김담당<small>manager@example.internal</small></td><td>관리자</td><td>${badge('활성','done')}</td><td>공동 PO·업무 관리, 계정·권한 관리</td></tr><tr><td>이담당<small>staff@example.internal</small></td><td>업무담당자</td><td>${badge('활성','done')}</td><td>모든 PO·업무 공동 조회·수정</td></tr></tbody></table></div></section><div class="demo-note">이 화면은 권한 구성을 보여주는 목업입니다. 실제 계정 생성·비밀번호 변경은 실행하지 않습니다. 모든 변경과 완료에는 처리자를 기록합니다.</div>`);}
function guide(){const items=[['01','업무 달력','월간·주간 보기, 고객·국내외 필터, 개별 업무와 세부 체크, 일정 이동.','#/calendar'],['02','PO 목록·출고','100개 주문 중 70개 출고·30개 잔량. 회차 추가, 수량·출고일 수정, ETD·ETA 확인.','#/orders/bj'],['03','업로드·확인','예시 원본과 인식값 비교. 국내·해외, 수량·단가·납기 수정 후 예시 PO 등록.','#/upload'],['04','문자 알림','평일 09시, 오늘+지연 업무 안내. 실패·불명확 결과와 재시도 이력.','#/settings']];shell(`${header('다음 수정을 위한 UI 목업','최종 설계서의 화면과 주요 업무 상태를 클릭하며 검토합니다.')}<div class="guide-grid">${items.map(([n,title,text,href])=>`<article class="card guide-item"><span class="number">SCREEN / ${n}</span><h2>${title}</h2><p>${text}</p><a href="${href}">화면 살펴보기 →</a></article>`).join('')}</div><section class="card card-body" style="margin-top:20px"><h2>목업의 데이터와 실제 업무</h2><p class="note">이 목업은 별도 브라우저 저장공간을 사용합니다. 변경 사항은 이 브라우저에만 저장되며 실제 웹앱의 PO·원본 파일·문자 설정에 영향을 주지 않습니다. 예시 데이터 초기화 버튼으로 처음 상태로 되돌릴 수 있습니다.</p><p class="note">실제 파일 OCR·문자 발송·계정 관리·원본 파일 보관은 연결하지 않습니다. 기준일은 예시를 비교하기 쉽도록 2026.10.19로 고정했습니다.</p></section>`);}
function render(){const path=(location.hash.slice(2)||'calendar').split('?')[0].split('/');if(path[0]==='orders'&&path[1])detail(path[1]);else({calendar,orders:ordersPage,upload,settings,history,users,guide}[path[0]]||calendar)();}
function close(){document.querySelector('#overlay').innerHTML='';document.body.style.overflow='';}
function show(content,drawer=false){document.querySelector('#overlay').innerHTML=`<div class="shade ${drawer?'':'dialog-shade'}"><section class="${drawer?'drawer':'dialog'}" role="dialog" aria-modal="true" aria-label="${drawer?'업무 상세':'처리 확인'}" tabindex="-1">${content}</section></div>`;document.body.style.overflow='hidden';document.querySelector('#overlay section').focus();}
function taskDetail(id){const t=state.tasks.find(t=>t.id===id),o=order(t.order);const s=o.shipments.find(s=>s.id===t.shipment);const complete=done(t);show(`<div class="drawer-head"><h2>업무 상세</h2>${btn(icon('close'),'close','quiet','aria-label="닫기"')}</div><div class="row">${badge(o.type==='domestic'?'국내':'해외',o.type)}${badge(labels[status(t)],status(t))}${t.manual?badge('수동 지정','manual'):''}</div><h3 style="margin:15px 0 9px">${esc(t.title)}</h3><p class="muted" style="font-size:12px">${esc(o.customer)} · ${esc(o.po)} ${s?'· '+(o.shipments.indexOf(s)+1)+'차':''}</p>${t.review?`<div class="alert">기준정보 변경 후 재확인 필요 · 기존 완료 기록은 보존됩니다.</div>`:''}${!t.date?'<div class="alert">ETD 미정 · 업무일과 문자 발송을 보류합니다.</div>':''}<div class="drawer-section"><dl class="definition"><dt>대상 품목</dt><dd>${esc(o.code)} · ${esc(o.name)}</dd><dt>대상 수량</dt><dd>${num(s?.qty||o.qty)} ${o.unit}</dd><dt>원래 기준일</dt><dd>${o.type==='domestic'?s?.date:s?.etd||o.received}</dd><dt>자동 계산일</dt><dd>${t.auto||'ETD 미정'}</dd><dt>최종 업무일</dt><dd><b>${t.date||'날짜 미정'}</b>${t.manual?' · 수동 지정':''}</dd></dl></div><div class="drawer-section"><div class="row between"><h4>세부 할 일</h4><small>${t.steps.filter(s=>s.done).length}/${t.steps.length} 완료</small></div>${t.steps.map((step,i)=>`<label class="check"><input type="checkbox" data-step="${i}" data-task-id="${t.id}" ${step.done?'checked':''} ${complete||t.cancelled?'disabled':''}><span>${esc(step.label)}${step.done?'<small>김담당 · 예시 완료 기록</small>':''}</span></label>`).join('')}<p class="note">모든 세부 작업을 완료하면 업무가 완료됩니다. 이 체크로 출고실적이 확정되지는 않습니다.</p></div>${complete?`<div class="drawer-section"><h4>완료 업무 재확인</h4><p class="note">기존 완료 이력을 보존하고 재작업 여부를 선택합니다.</p><div class="row wrap">${btn('재작업 필요','reopen','primary',`data-id="${t.id}"`)}${btn('재작업 없이 확인','reviewed','',`data-id="${t.id}"`)}</div></div>`:t.cancelled?'':`<form id="move-form" data-task-id="${t.id}" class="drawer-section"><h4>업무일 이동</h4><label class="field">최종 업무일<input name="date" type="date" value="${t.date||''}" ${t.auto?'':'disabled'} required></label><div class="row" style="margin-top:13px"><button class="btn primary" ${t.auto?'':'disabled'}>업무일 저장</button>${btn('자동일정으로 되돌리기','auto-date','',`data-id="${t.id}"`)}</div><p class="note">직접 지정한 날짜는 자동 재계산으로 덮어쓰지 않습니다. 문자도 최종 업무일을 따릅니다.</p></form>`}<div class="drawer-section"><a href="#/orders/${o.id}" class="btn" data-action="close">PO 상세로 이동 →</a></div>`,true);}
function shipmentForm(o,s){const isNew=!s;const completed=s?.done;show(`<div class="row between"><h2>${isNew?'회차 추가':completed?o.type==='overseas'?'완료 선적 ETA 수정':'출고실적 정정':'날짜·수량 수정'}</h2>${btn('✕','close','quiet','aria-label="닫기"')}</div><p class="note">${esc(o.customer)} · ${esc(o.po)}</p><form id="shipment-form" data-order-id="${o.id}" data-shipment-id="${s?.id||''}"><div class="form-grid" style="margin-top:20px"><label class="field wide">회차 수량 (${o.unit})<input name="qty" type="number" step="any" min="0.0000000001" value="${s?.qty??''}" ${completed&&o.type==='overseas'?'readonly':''} required></label>${o.type==='domestic'?`<label class="field wide">출고일<input type="date" name="date" value="${s?.date||'2026-10-23'}" ${completed?'readonly':''} required></label>`:`<label class="field">ETD · 미정 허용<input type="date" name="etd" value="${s?.etd||''}" ${completed?'readonly':''}></label><label class="field">ETA · 고객 안내용<input type="date" name="eta" value="${s?.eta||''}"></label>`}${completed&&o.type==='domestic'?'<label class="field wide">정정 사유<input name="reason" required placeholder="출고실적을 정정하는 사유"></label>':''}</div><p class="note">수량은 회차별로 한 번 입력합니다. 출고 완료 전에는 실적으로 계산하지 않습니다.</p><div class="actions">${btn('취소','close')}<button class="btn primary">저장</button></div></form>`);}
document.addEventListener('click',e=>{
 const target=e.target.closest('[data-action],[data-date],[data-task],[data-order],[data-view],[data-filter],[data-detail-tab]');if(!target)return;
 if(target.dataset.date){selected=target.dataset.date;calendar();return;}if(target.dataset.task){taskDetail(target.dataset.task);return;}if(target.dataset.order){location.hash='#/orders/'+target.dataset.order;return;}if(target.dataset.view){view=target.dataset.view;calendar();return;}if(target.dataset.filter){type=target.dataset.filter;render();return;}if(target.dataset.detailTab){detailTab=target.dataset.detailTab;render();return;}
 const action=target.dataset.action,id=target.dataset.id,o=order(id),t=state.tasks.find(t=>t.id===id);const s=o?.shipments.find(s=>s.id===target.dataset.shipment);
 if(action==='close'){close();return;}
 if(action==='reset'){if(confirm('목업의 예시 데이터를 처음 상태로 되돌릴까요? 실제 웹앱에는 영향을 주지 않습니다.')){state=freshState();save();close();render();toast('예시 데이터를 초기화했습니다.');}return;}
 if(['previous','next','today'].includes(action)){if(action==='today'){selected=TODAY;month=TODAY.slice(0,7)+'-01';}else if(view==='week'){selected=shift(selected,action==='next'?7:-7);month=selected.slice(0,7)+'-01';}else{const d=new Date(month+'T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+(action==='next'?1:-1));month=d.toISOString().slice(0,10);}calendar();return;}
 if(action==='add-shipment'||action==='edit-shipment'){shipmentForm(o,s);return;}
 if(action==='confirm-shipment'){if(o.type==='overseas'&&!s.etd){toast('선적 완료 전 ETD를 입력하세요.');return;}s.done=true;o.history.unshift('10.19 · 김담당 · '+num(s.qty)+' '+o.unit+' 출고 완료');save();render();toast('출고실적을 확정하고 잔량을 갱신했습니다.');return;}
 if(action==='cancel-shipment'){if(confirm('이 회차의 배정을 해제하고 미완료 업무를 취소할까요?')){s.cancelled=true;reconcile(state);o.history.unshift('10.19 · 김담당 · 미완료 회차 취소');save();render();toast('회차의 배정을 해제했습니다. 주문수량은 유지됩니다.');}return;}
 if(action==='auto-date'){t.manual=null;t.date=t.auto;t.recalc=false;save();render();taskDetail(id);toast('자동 계산일로 되돌렸습니다.');return;}
 if(action==='reopen'){t.steps.forEach(step=>step.done=false);t.date=t.auto?(t.manual||t.auto):null;t.review=false;save();render();taskDetail(id);toast('이전 완료 기록을 남기고 재작업으로 전환했습니다.');return;}
 if(action==='reviewed'){t.review=false;save();render();taskDetail(id);toast('완료 상태를 유지하고 재확인했습니다.');return;}
 if(action==='notice-detail'){const n=state.history.find(v=>v.id===id);show(`<div class="row between"><h2>문자 발송 상세</h2>${btn('✕','close','quiet','aria-label="닫기"')}</div><p class="note">${n.at} · ${n.kind}</p>${badge(n.status,n.status==='전달 완료'?'done':'failed')}<div class="drawer-section"><dl class="definition"><dt>수신자</dt><dd>사용자 본인 · 010-****-0000</dd><dt>시도 횟수</dt><dd>${n.attempt}회</dd><dt>처리 사유</dt><dd>${n.status==='전달 완료'?'공급자 전달 결과 확인':n.status==='최종 실패'?'최초 요청 후 5분 간격 3회 재시도에도 명확한 실패가 반환됨. 등록 번호·서비스 상태 확인 필요.':'요청 결과 불명확. 공급자 내역을 조회하여 중복 발송 방지. 자동 재발송 보류.'}</dd><dt>업무 대상</dt><dd>${n.count}건 · 완료·취소·날짜 상태 재확인</dd></dl></div><p class="demo-note">발송 상태와 사유는 UI 예시입니다. 실제 발송은 하지 않습니다.</p>`);}
});
document.addEventListener('change',e=>{if(e.target.id==='customer-filter'){customer=e.target.value;calendar();}if(e.target.id==='sample-file'){const file=e.target.files[0];document.querySelector('#file-name').textContent=file?file.name+' · 선택됨 (예시 인식값 사용)':'파일을 선택하세요.';}if(e.target.matches('[data-step]')){const t=state.tasks.find(t=>t.id===e.target.dataset.taskId);t.steps[Number(e.target.dataset.step)].done=e.target.checked;if(done(t))t.completed='김담당 · 예시 기준일';save();render();taskDetail(t.id);toast(done(t)?'모든 세부 작업을 완료했습니다.':'작업 상태를 저장했습니다.');}});
document.addEventListener('input',e=>{if(e.target.id==='order-search'){const start=e.target.selectionStart;search=e.target.value;ordersPage();const field=document.querySelector('#order-search');field.focus();field.setSelectionRange(start,start);}});
document.addEventListener('submit',e=>{
 e.preventDefault();const form=e.target;const values=Object.fromEntries(new FormData(form));
 if(form.id==='move-form'){const t=state.tasks.find(t=>t.id===form.dataset.taskId);if([0,6].includes(weekday(values.date))){toast('사내 업무일은 평일로 지정하세요.');return;}t.manual=values.date;t.date=values.date;save();render();taskDetail(t.id);toast('업무일을 옮겼습니다. 문자도 변경한 날짜를 따릅니다.');}
 if(form.id==='notice-form'){state.notice={...values,enabled:form.elements.enabled.checked};save();toast('목업 설정을 저장했습니다. 실제 문자는 발송하지 않습니다.');}
 if(form.id==='shipment-form'){const o=order(form.dataset.orderId);const existing=o.shipments.find(s=>s.id===form.dataset.shipmentId);const qty=Number(values.qty);const quantities=o.shipments.filter(s=>s!==existing&&!s.cancelled).map(s=>s.qty).concat(qty);if(!validateAllocation(o.qty,quantities,o.cancelledQty)){toast('회차 배정 합계가 주문수량을 초과하거나 수량이 올바르지 않습니다.');return;}if(o.type==='domestic'&&[0,6].includes(weekday(values.date))){toast('국내 출고일은 평일로 지정하세요.');return;}const s=existing||{id:'s'+Date.now(),done:false};Object.assign(s,{qty,date:values.date,etd:values.etd||null,eta:values.eta||null});if(!existing)o.shipments.push(s);o.history.unshift('10.19 · 김담당 · '+(existing?'회차 수정':'회차 추가')+(values.reason?' / '+values.reason:''));reconcile(state);save();close();render();toast('회차를 저장하고 연결된 일정을 갱신했습니다.');}
 if(form.id==='review-form'){if(state.orders.some(o=>o.po===values.po&&o.customer===values.customer)){toast('같은 고객·PO 번호가 있습니다. 수정본으로 비교하세요.');return;}if(Number(values.qty)<=0){toast('주문수량을 확인하세요.');return;}const id='demo'+Date.now();const o={...values,id,qty:Number(values.qty),cancelledQty:0,shipments:[{id:'s1',qty:Number(values.qty),done:false,date:values.type==='domestic'?values.due:null,etd:null,eta:null}],history:['10.19 · 김담당 · 인식값 확인 후 예시 PO 등록']};if(o.type==='domestic'&&[0,6].includes(weekday(o.shipments[0].date))){while([0,6].includes(weekday(o.shipments[0].date)))o.shipments[0].date=shift(o.shipments[0].date,1);}state.orders.push(o);reconcile(state);save();detailTab='overview';location.hash='#/orders/'+id;toast('예시 PO와 업무를 생성했습니다. 실제 웹앱에는 등록되지 않습니다.');}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&document.querySelector('#overlay [role=dialog]')){const dialog=document.querySelector('#overlay [role=dialog]');const focusable=[...dialog.querySelectorAll('a,button,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{close();render();window.scrollTo(0,0);});
render();
